    }
  ],
  "minority_signals": [
    {
      "signal": "Recorded sales price trend is 'rising' with 100 comps in 12 months and the metro HPI still positive — one could argue for a 'buy' on momentum.",
      "note": "The 45% five-year run and 6.65% rate environment mean the market is mid-to-late cycle with compressed affordability. Momentum is real but the risk-adjusted entry is not compelling enough to upgrade from hold to buy without a clearer rate tailwind or a specific below-median comp opportunity."
    }
  ]
